 public V18CenterWindow(){InitializeComponent();InstalledVersionText.Text=$"Installed version: {GetType().Assembly.GetName().Version}";_refreshTimer.Tick+=async(_,_)=>await RefreshConnectionsAsync();Loaded+=V18CenterWindow_Loaded;Closing+=(_,_)=>SaveUiState();Closed+=(_,_)=>{_refreshTimer.Stop();_connectionCts?.Cancel();_connectionCts?.Dispose();_limitNotifier.Dispose();};}
