 static string Data(double kb)=>DisplayFormatter.Data(kb);
 void RestoreUiState(){_ui=_uiStore.Load();Width=_ui.Width;Height=_ui.Height;if(!double.IsNaN(_ui.Left)&&!double.IsNaN(_ui.Top)){Left=_ui.Left;Top=_ui.Top;}CenterTabs.SelectedIndex=Math.Clamp(_ui.SelectedTab,0,CenterTabs.Items.Count-1);ConnectionSearchBox.Text=_ui.ConnectionSearch;_historyDays=_ui.HistoryDays is 1 or 7 or 30?_ui.HistoryDays:7;int[] seconds={0,2,5,10};int index=Array.IndexOf(seconds,_ui.RefreshSeconds);RefreshIntervalBox.SelectedIndex=index<0?0:index;}
