 void LoadLimit(){var settings=_limits.Load();AllowanceBox.Text=settings.AllowanceGB.ToString("0.##");CycleDayBox.Text=settings.CycleStartDay.ToString();LimitEnabledBox.IsChecked=settings.Enabled;LimitNotificationsBox.IsChecked=settings.NotificationsEnabled;var cycle=DataLimitService.GetCycle(settings.CycleStartDay);using var history=new UsageHistoryService();var totals=history.QueryTotals(cycle.Start,cycle.End);var snap=new DataLimitSnapshot(cycle.Start,cycle.End,totals.Down,totals.Up,settings.AllowanceGB*1024*1024);UsedText.Text=Data(snap.TotalKB);RemainingText.Text=Data(snap.RemainingKB);ForecastText.Text=snap.ElapsedDays<2?"Collecting data":Data(snap.ForecastKB);UsageProgress.Value=Math.Min(100,snap.Percent);string forecast=snap.ElapsedDays<2?"Collecting data":snap.ForecastKB>snap.AllowanceKB?"Projected over limit":snap.ForecastKB>snap.AllowanceKB*.85?"Near limit":"On track";PercentText.Text=$"{snap.Percent:F1}% used • {forecast}";CycleText.Text=$"Cycle: {cycle.Start:dd MMM yyyy} to {cycle.End.AddDays(-1):dd MMM yyyy} • Down {Data(snap.DownloadKB)} • Up {Data(snap.UploadKB)}";EvaluateLimitNotification(settings,snap,cycle.Start);}
 void EvaluateLimitNotification(DataLimitSettings settings,DataLimitSnapshot snap,DateTime cycleStart){if(!settings.Enabled||!settings.NotificationsEnabled)return;string key=cycleStart.ToString("yyyy-MM-dd");if(settings.LastNotifiedCycle!=key){settings.LastNotifiedCycle=key;settings.HighestNotifiedThreshold=0;}int crossed=settings.NotificationThresholds.Where(x=>x<=snap.Percent).DefaultIfEmpty(0).Max();if(crossed>settings.HighestNotifiedThreshold){settings.HighestNotifiedThreshold=crossed;_limits.Save(settings);_limitNotifier.Show($"Data limit: {crossed}% used",$"Current cycle usage is {Data(snap.TotalKB)} of {settings.AllowanceGB:0.##} GB. Remaining: {Data(snap.RemainingKB)}.");}}
 void SaveLimit_Click(object s,RoutedEventArgs e){if(!double.TryParse(AllowanceBox.Text,out var a)||a<=0||!int.TryParse(CycleDayBox.Text,out var d)||d<1||d>28){System.Windows.MessageBox.Show(this,"Use an allowance above 0 GB and a cycle day from 1 to 28.","Data limit",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Warning);return;}var current=_limits.Load();current.Enabled=LimitEnabledBox.IsChecked==true;current.NotificationsEnabled=LimitNotificationsBox.IsChecked==true;current.AllowanceGB=a;current.CycleStartDay=d;_limits.Save(current);LoadLimit();}
 async void RefreshConnections_Click(object s,RoutedEventArgs e)=>await RefreshConnectionsAsync();
 async Task RefreshConnectionsAsync()
 {
  _connectionCts?.Cancel();_connectionCts?.Dispose();_connectionCts=new();var token=_connectionCts.Token;_scanStarted=DateTime.UtcNow;
  try
  {
   ConnectionStatusText.Text="Loading connections in background...";
   var rows=await Task.Run(()=>{token.ThrowIfCancellationRequested();return _connections.GetConnections();},token);
   token.ThrowIfCancellationRequested();var selected=(ConnectionsGrid.SelectedItem as ConnectionRow)?.RemoteEndpoint;_connectionRows=rows;ConnectionsGrid.ItemsSource=_connectionRows;ApplyConnectionFilter();if(selected is not null)ConnectionsGrid.SelectedItem=_connectionRows.FirstOrDefault(x=>x.RemoteEndpoint==selected);ConnectionStatusText.Text=$"{_connectionRows.Count} endpoints • refreshed in {(DateTime.UtcNow-_scanStarted).TotalMilliseconds:F0} ms";
  }
  catch(OperationCanceledException){}
  catch(Exception ex){ConnectionStatusText.Text="Unable to read connections: "+ex.Message;}
 }
 void ConnectionSearchBox_TextChanged(object s,System.Windows.Controls.TextChangedEventArgs e)=>ApplyConnectionFilter();void ApplyConnectionFilter(){if(ConnectionsGrid.ItemsSource is null)return;string q=ConnectionSearchBox?.Text?.Trim()??"";var view=CollectionViewSource.GetDefaultView(ConnectionsGrid.ItemsSource);view.Filter=o=>o is ConnectionRow r&&(q.Length==0||r.ProcessName.Contains(q,StringComparison.OrdinalIgnoreCase)||r.Description.Contains(q,StringComparison.OrdinalIgnoreCase)||r.Publisher.Contains(q,StringComparison.OrdinalIgnoreCase)||r.LocalEndpoint.Contains(q,StringComparison.OrdinalIgnoreCase)||r.RemoteEndpoint.Contains(q,StringComparison.OrdinalIgnoreCase)||r.PidText.Contains(q,StringComparison.OrdinalIgnoreCase));view.Refresh();}
 ConnectionRow? SelectedConnection=>ConnectionsGrid.SelectedItem as ConnectionRow;void CopyRemote_Click(object s,RoutedEventArgs e){if(SelectedConnection is { } r)System.Windows.Clipboard.SetText(r.RemoteEndpoint);}void ConnectionOpenLocation_Click(object s,RoutedEventArgs e){if(SelectedConnection is { ExecutablePath.Length:>0 } r)Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{r.ExecutablePath}\""){UseShellExecute=true});}void ConnectionsGrid_MouseDoubleClick(object s,System.Windows.Input.MouseButtonEventArgs e)=>ConnectionOpenLocation_Click(s,e);void ConnectionEndTask_Click(object s,RoutedEventArgs e)
 {
  var r=SelectedConnection;if(r is null)return;int ownPid=Environment.ProcessId;
  if(r.ProcessId is 0 or 4||r.ProcessId==ownPid){System.Windows.MessageBox.Show(this,"This protected or current application process cannot be ended here.","End task blocked",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Warning);return;}
  try
  {
   using var process=Process.GetProcessById(r.ProcessId);string currentName=process.ProcessName+".exe";
   if(!currentName.Equals(r.ProcessName,StringComparison.OrdinalIgnoreCase)){System.Windows.MessageBox.Show(this,"The PID is now owned by a different process. Refresh the list and try again.","PID changed",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Warning);return;}
   string path="";try{path=process.MainModule?.FileName??"";}catch{}
   string confirmation = $"End process tree for {r.Description}?\nPID: {r.ProcessId}\nPath: {path}\n\nUnsaved work may be lost.";
   if(System.Windows.MessageBox.Show(this,confirmation,"End task",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Warning,System.Windows.MessageBoxResult.No)!=System.Windows.MessageBoxResult.Yes)return;
   process.Kill(true);_ = RefreshConnectionsAsync();
  }
  catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,"End task failed",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Error);}
 }
