 void RefreshIntervalBox_SelectionChanged(object s,System.Windows.Controls.SelectionChangedEventArgs e){if(RefreshIntervalBox.SelectedItem is not System.Windows.Controls.ComboBoxItem item||!int.TryParse(item.Tag?.ToString(),out int seconds))return;_refreshTimer.Stop();if(seconds>0){_refreshTimer.Interval=TimeSpan.FromSeconds(seconds);_refreshTimer.Start();}}
