 void RefreshDiagnostics_Click(object s,RoutedEventArgs e)=>RefreshDiagnostics();void RefreshDiagnostics()=>DiagnosticsBox.Text=_diagnostics.BuildReport();void CopyDiagnostics_Click(object s,RoutedEventArgs e)=>System.Windows.Clipboard.SetText(DiagnosticsBox.Text);void ExportDiagnostics_Click(object s,RoutedEventArgs e){var dialog=new Microsoft.Win32.SaveFileDialog{Title="Export sanitized diagnostics",Filter="ZIP archive (*.zip)|*.zip",FileName=$"SiamNetworkMonitor-Diagnostics-{DateTime.Now:yyyyMMdd-HHmm}.zip"};if(dialog.ShowDialog(this)==true){_diagnosticsExport.Export(dialog.FileName,DiagnosticsBox.Text);System.Windows.MessageBox.Show(this,"Sanitized diagnostics were exported successfully.","Diagnostics",System.Windows.MessageBoxButton.OK,System.Windows.MessageBoxImage.Information);}}
 void HistoryPeriod_Click(object s,RoutedEventArgs e){if(s is System.Windows.Controls.Button b&&int.TryParse(b.Tag?.ToString(),out var days)){_historyDays=days;LoadHistory(days);SaveUiState();}}void LoadHistory(int days){using var h=new UsageHistoryService();DateTime since=days==1?DateTime.Today:DateTime.Now.AddDays(-days);var b=h.QueryBuckets(since);var g=(days==1?b.GroupBy(x=>x.Hour):b.GroupBy(x=>x.Hour.Date)).Select(x=>(Time:x.Key,Down:x.Sum(y=>y.DownloadKB),Up:x.Sum(y=>y.UploadKB))).OrderBy(x=>x.Time).ToList();HistoryChart.SetPoints(g);var top=b.GroupBy(x=>x.Application,StringComparer.OrdinalIgnoreCase).Select(x=>new HistoryAppRow(x.Key,x.Sum(y=>y.DownloadKB),x.Sum(y=>y.UploadKB))).OrderByDescending(x=>x.TotalKB).Take(10).ToList();TopAppsGrid.ItemsSource=top;HistoryStatusText.Text=$"{(days==1?"Today":$"Last {days} days")} • {g.Count} points • Top {top.Count} apps";}sealed record HistoryAppRow(string Application,double DownloadKB,double UploadKB){public double TotalKB=>DownloadKB+UploadKB;public string Download=>DisplayFormatter.Data(DownloadKB);public string Upload=>DisplayFormatter.Data(UploadKB);public string Total=>DisplayFormatter.Data(TotalKB);}
